import { HttpException, HttpStatus, Injectable } from '@nestjs/common';
import { AppException } from '../../common/errors/app-exception';
import { BUSINESS_ERROR_CODES } from '../../common/errors/error-codes';
import { CompanyService } from '../company/company.module';
import { ContactService } from '../contact/contact.service';
import {
  CreateDealDto,
  DealCompanySummary,
  DealDetailResponseDto,
  DealListQueryDto,
  UpdateDealDto,
} from './dto';
import { DealEntity } from './deal.entity';
import { DealRepository } from './deal.repository';

@Injectable()
export class DealService {
  constructor(
    private readonly dealRepository: DealRepository,
    private readonly companyService: CompanyService,
    private readonly contactService: ContactService,
  ) {}

  async createDeal(dto: CreateDealDto): Promise<DealEntity> {
    await this.ensureCompanyExists(dto.companyId);
    await this.ensureContactIsValidForCompany(dto.contactId, dto.companyId);

    const deal = this.dealRepository.create(dto);
    return await this.dealRepository.save(deal);
  }

  async getDeals(query: DealListQueryDto) {
    return await this.dealRepository.findWithFilter(query);
  }

  async getDealById(id: string): Promise<DealDetailResponseDto> {
    const deal = await this.getDealEntityById(id);
    const company = await this.companyService.getCompanyById(deal.companyId);

    const companySummary: DealCompanySummary = {
      id: company.id,
      name: company.name,
      status: company.status,
      industry: company.industry,
    };

    return {
      ...deal,
      company: companySummary,
    };
  }

  async updateDeal(id: string, dto: UpdateDealDto): Promise<DealEntity> {
    if (Object.keys(dto).length === 0) {
      throw new AppException({
        statusCode: HttpStatus.BAD_REQUEST,
        code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
        message: 'At least one field must be provided for update.',
        details: {
          errors: [
            {
              field: 'body',
              messages: ['At least one field must be provided for update.'],
            },
          ],
        },
      });
    }

    const existingDeal = await this.getDealEntityById(id);
    const targetCompanyId = dto.companyId ?? existingDeal.companyId;
    const hasContactIdInPayload = Object.prototype.hasOwnProperty.call(
      dto,
      'contactId',
    );
    const targetContactId = hasContactIdInPayload
      ? (dto.contactId ?? null)
      : existingDeal.contactId;

    if (dto.companyId && dto.companyId !== existingDeal.companyId) {
      await this.ensureCompanyExists(dto.companyId);
    }

    await this.ensureContactIsValidForCompany(targetContactId, targetCompanyId);

    const updatedDeal = this.dealRepository.merge(existingDeal, dto);
    return await this.dealRepository.save(updatedDeal);
  }

  async removeDeal(id: string): Promise<void> {
    await this.getDealEntityById(id);
    await this.dealRepository.softDelete(id);
  }

  private async getDealEntityById(id: string): Promise<DealEntity> {
    const deal = await this.dealRepository.findOne({ where: { id } });

    if (!deal) {
      throw new AppException({
        statusCode: HttpStatus.NOT_FOUND,
        code: BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
        message: `Deal with ID ${id} not found`,
        details: {
          resource: 'Deal',
          id,
        },
      });
    }

    return deal;
  }

  private async ensureCompanyExists(companyId: string): Promise<void> {
    try {
      await this.companyService.getCompanyById(companyId);
    } catch (error) {
      if (error instanceof HttpException && error.getStatus() === 404) {
        throw new AppException({
          statusCode: HttpStatus.NOT_FOUND,
          code: BUSINESS_ERROR_CODES.PARENT_NOT_FOUND,
          message: `Company with ID ${companyId} not found`,
          details: {
            resource: 'Company',
            id: companyId,
          },
        });
      }

      throw error;
    }
  }

  private async ensureContactIsValidForCompany(
    contactId: string | null | undefined,
    companyId: string,
  ): Promise<void> {
    if (!contactId) {
      return;
    }

    try {
      const contact = await this.contactService.getContactById(contactId);

      if (contact.companyId !== companyId) {
        throw new AppException({
          statusCode: HttpStatus.BAD_REQUEST,
          code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
          message: `Contact with ID ${contactId} does not belong to company ${companyId}`,
          details: {
            errors: [
              {
                field: 'contactId',
                messages: [
                  `Contact with ID ${contactId} does not belong to company ${companyId}`,
                ],
              },
            ],
          },
        });
      }
    } catch (error) {
      if (error instanceof HttpException && error.getStatus() === 404) {
        throw new AppException({
          statusCode: HttpStatus.NOT_FOUND,
          code: BUSINESS_ERROR_CODES.PARENT_NOT_FOUND,
          message: `Contact with ID ${contactId} not found`,
          details: {
            resource: 'Contact',
            id: contactId,
          },
        });
      }

      throw error;
    }
  }
}
