    // Verifies edge-case seed covers nulls, long fields, pagination, and valid links.
    runSeedCommand('npm run db:reset:seed:edge-case');

    const [{ count: companyCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "companies"
        WHERE "name" LIKE 'Edge Seed Company%'
           OR "name" LIKE 'Edge Seed Company Long Name%'
      `,
    );
    const [{ count: emptyCompanyCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "companies" company
        WHERE company.name = 'Edge Seed Company 00 Empty Contacts'
          AND NOT EXISTS (
            SELECT 1
            FROM "contacts" contact
            WHERE contact."companyId" = company.id
          )
      `,
    );
    const [{ count: nullFieldCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "companies"
        WHERE "name" = 'Edge Seed Company 01 Missing Fields'
          AND "email" IS NULL
          AND "phone" IS NULL
          AND "website" IS NULL
      `,
    );
    const [{ count: longNameCompanyCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "companies"
        WHERE "name" LIKE 'Edge Seed Company Long Name%'
          AND LENGTH("name") >= 250
      `,
    );
    const [{ count: maxLengthRoleCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "contacts"
        WHERE LENGTH(COALESCE("role", '')) = 100
      `,
    );
    const [{ count: orphanCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "contacts" contact
        LEFT JOIN "companies" company ON company.id = contact."companyId"
        WHERE company.id IS NULL
      `,
    );
    const [{ count: edgeDealCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "deals"
        WHERE "name" LIKE 'Edge Seed Company Deal%'
           OR "name" LIKE 'Edge Seed Company Deal %'
      `,
    );
    const [{ count: nullContactDealCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "deals"
        WHERE "contactId" IS NULL
      `,
    );
    const [{ count: nullExpectedCloseDateCount }] = await dataSource.query(
      `
        SELECT COUNT(*)::int AS count
        FROM "deals"
        WHERE "expectedCloseDate" IS NULL
      `,
    );

    expect(companyCount).toBe(25);
    expect(emptyCompanyCount).toBe(1);
    expect(nullFieldCount).toBe(1);
    expect(longNameCompanyCount).toBeGreaterThanOrEqual(1);
    expect(maxLengthRoleCount).toBeGreaterThanOrEqual(1);
    expect(orphanCount).toBe(0);
    expect(edgeDealCount).toBeGreaterThanOrEqual(8);
    expect(nullContactDealCount).toBeGreaterThanOrEqual(1);
    expect(nullExpectedCloseDateCount).toBeGreaterThanOrEqual(1);
  });
});

function runSeedCommand(command: string) {
  execSync(command, {
    cwd: resolve(__dirname, '../'),
    stdio: 'pipe',
  });
}

import { DataSource } from 'typeorm';
import {
  closeTestDataSource,
  getTestDataSource,
  listConstraintNames,
  listIndexNames,
} from './setup/test-database';

jest.setTimeout(30000);

describe('Database migrations (e2e)', () => {
  let dataSource: DataSource;

  beforeAll(async () => {
    dataSource = await getTestDataSource();
  });

  afterAll(async () => {
    await closeTestDataSource();
  });

  beforeEach(async () => {
    await dataSource.query('DROP SCHEMA IF EXISTS public CASCADE');
    await dataSource.query('CREATE SCHEMA public');
    await dataSource.query('CREATE EXTENSION IF NOT EXISTS "uuid-ossp"');
    await dataSource.query('CREATE EXTENSION IF NOT EXISTS "pgcrypto"');
    await dataSource.synchronize();
  });

  it('runs the migration on a clean schema', async () => {
    // Verifies migrations create expected contact and deal constraints/indexes.
    await dataSource.runMigrations();

    await expect(listConstraintNames(dataSource, 'contacts')).resolves.toEqual(
      expect.arrayContaining(['fk_contacts_company_id']),
    );
    await expect(listIndexNames(dataSource, 'contacts')).resolves.toEqual(
      expect.arrayContaining(['idx_contacts_company_id']),
    );
    await expect(listConstraintNames(dataSource, 'deals')).resolves.toEqual(
      expect.arrayContaining(['fk_deals_company_id', 'fk_deals_contact_id']),
    );
    await expect(listIndexNames(dataSource, 'deals')).resolves.toEqual(
      expect.arrayContaining([
        'idx_deals_company_id',
        'idx_deals_contact_id',
        'idx_deals_stage',
      ]),
    );
  });

  it('rolls back the migration', async () => {
    // Verifies rolling back the latest migration removes deal artifacts only.
    await dataSource.runMigrations();
    await dataSource.undoLastMigration();

    await expect(listConstraintNames(dataSource, 'deals')).resolves.not.toContain(
      'fk_deals_company_id',
    );
    await expect(listConstraintNames(dataSource, 'deals')).resolves.not.toContain(
      'fk_deals_contact_id',
    );
    await expect(listIndexNames(dataSource, 'deals')).resolves.not.toContain(
      'idx_deals_company_id',
    );
    await expect(listIndexNames(dataSource, 'deals')).resolves.not.toContain(
      'idx_deals_contact_id',
    );
    await expect(listIndexNames(dataSource, 'deals')).resolves.not.toContain(
      'idx_deals_stage',
    );
    await expect(
      listConstraintNames(dataSource, 'contacts'),
    ).resolves.toContain('fk_contacts_company_id');
  });

  it('can rerun the migration after rollback', async () => {
    // Verifies the latest migration can be applied again after rollback.
    await dataSource.runMigrations();
    await dataSource.undoLastMigration();
    await dataSource.runMigrations();

    await expect(listConstraintNames(dataSource, 'deals')).resolves.toEqual(
      expect.arrayContaining(['fk_deals_company_id', 'fk_deals_contact_id']),
    );
  });

  it('prevents orphan companyId values', async () => {
    // Verifies the foreign key blocks orphan contact rows.
    await dataSource.runMigrations();

    await expect(
      dataSource.query(
        `
          INSERT INTO "contacts" ("id", "companyId", "name", "email", "phone", "role", "createdAt", "updatedAt")
          VALUES (gen_random_uuid(), $1, 'Orphan Contact', 'orphan@test.local', '0200-7777', 'User', NOW(), NOW())
        `,
        ['7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1aa'],
      ),
    ).rejects.toThrow(/fk_contacts_company_id/i);
  });

  it('prevents orphan foreign keys on deals', async () => {
    // Verifies deal company/contact foreign keys reject orphan references.
    await dataSource.runMigrations();

    await expect(
      dataSource.query(
        `
          INSERT INTO "deals" ("id", "name", "value", "stage", "companyId", "contactId", "createdAt", "updatedAt")
          VALUES (gen_random_uuid(), 'Orphan Deal Company', 1000, 'lead', $1, NULL, NOW(), NOW())
        `,
        ['7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1aa'],
      ),
    ).rejects.toThrow(/fk_deals_company_id/i);

    const [{ id: companyId }] = await dataSource.query(
      `
        INSERT INTO "companies" ("id", "name", "status", "createdAt", "updatedAt")
        VALUES (gen_random_uuid(), 'Deal FK Company', '1', NOW(), NOW())
        RETURNING "id"
      `,
    );

    await expect(
      dataSource.query(
        `
          INSERT INTO "deals" ("id", "name", "value", "stage", "companyId", "contactId", "createdAt", "updatedAt")
          VALUES (gen_random_uuid(), 'Orphan Deal Contact', 1000, 'lead', $1, $2, NOW(), NOW())
        `,
        [companyId, '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1ab'],
      ),
    ).rejects.toThrow(/fk_deals_contact_id/i);
  });
});

import { HttpStatus } from '@nestjs/common';
import { BUSINESS_ERROR_CODES } from '../../common/errors/error-codes';
import { AppException } from '../../common/errors/app-exception';
import { ContactService } from './contact.service';

describe('ContactService', () => {
  const buildService = () => {
    const contactRepository = {
      create: jest.fn(),
      save: jest.fn(),
      findWithFilter: jest.fn(),
      findOne: jest.fn(),
      merge: jest.fn(),
      softDelete: jest.fn(),
    };

    const companyService = {
      getCompanyById: jest.fn(),
    };

    return {
      service: new ContactService(
        contactRepository as never,
        companyService as never,
      ),
      contactRepository,
      companyService,
    };
  };

  it('returns ENTITY_NOT_FOUND when the contact is missing', async () => {
    // Verifies missing contacts return the not-found business error.
    const { service, contactRepository } = buildService();
    contactRepository.findOne.mockResolvedValue(null);

    await expect(service.getContactById('missing-contact')).rejects.toMatchObject(
      {
        status: HttpStatus.NOT_FOUND,
        response: {
          code: BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
          details: {
            resource: 'Contact',
            id: 'missing-contact',
          },
        },
      },
    );
  });

  it('fails when moving a contact to a missing company', async () => {
    // Verifies reassignment fails when the target company does not exist.
    const { service, contactRepository, companyService } = buildService();
    contactRepository.findOne.mockResolvedValue({
      id: 'contact-1',
      companyId: 'company-1',
      name: 'Contact One',
    });
    companyService.getCompanyById.mockRejectedValue(
      new AppException({
        statusCode: HttpStatus.NOT_FOUND,
        code: BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
        message: 'Company not found',
      }),
    );

    await expect(
      service.updateContact('contact-1', { companyId: 'company-2' }),
    ).rejects.toMatchObject({
      status: HttpStatus.NOT_FOUND,
      response: {
        code: BUSINESS_ERROR_CODES.PARENT_NOT_FOUND,
        details: {
          resource: 'Company',
          id: 'company-2',
        },
      },
    });
    expect(contactRepository.save).not.toHaveBeenCalled();
  });

  it('saves the updated contact when the target company exists', async () => {
    // Verifies reassignment succeeds when the target company is valid.
    const { service, contactRepository, companyService } = buildService();
    const existingContact = {
      id: 'contact-2',
      companyId: 'company-1',
      role: 'User',
    };
    const mergedContact = {
      ...existingContact,
      companyId: 'company-3',
      role: 'Decision Maker',
    };

    contactRepository.findOne.mockResolvedValue(existingContact);
    companyService.getCompanyById.mockResolvedValue({ id: 'company-3' });
    contactRepository.merge.mockReturnValue(mergedContact);
    contactRepository.save.mockResolvedValue(mergedContact);

    await expect(
      service.updateContact('contact-2', {
        companyId: 'company-3',
        role: 'Decision Maker',
      }),
    ).resolves.toEqual(mergedContact);
  });
});
import { HttpStatus } from '@nestjs/common';
import { BUSINESS_ERROR_CODES } from '../../common/errors/error-codes';
import { CompanyService } from './company.service';

describe('CompanyService', () => {
  const createQueryBuilder = () => ({
    from: jest.fn().mockReturnThis(),
    where: jest.fn().mockReturnThis(),
    getCount: jest.fn(),
  });

  const buildService = () => {
    const queryBuilder = createQueryBuilder();
    const companyRepo = {
      create: jest.fn(),
      save: jest.fn(),
      findWithFilter: jest.fn(),
      findOne: jest.fn(),
      merge: jest.fn(),
      softDelete: jest.fn(),
      manager: {
        createQueryBuilder: jest.fn().mockReturnValue(queryBuilder),
      },
    };

    return {
      service: new CompanyService(companyRepo as never),
      companyRepo,
      queryBuilder,
    };
  };

  it('returns ENTITY_NOT_FOUND when the company is missing', async () => {
    // Verifies missing companies return the not-found business error.
    const { service, companyRepo } = buildService();
    companyRepo.findOne.mockResolvedValue(null);

    await expect(service.getCompanyById('missing-id')).rejects.toMatchObject({
      status: HttpStatus.NOT_FOUND,
      response: {
        code: BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
        details: {
          resource: 'Company',
          id: 'missing-id',
        },
      },
    });
  });

  it('blocks delete when the company still has contacts', async () => {
    // Verifies delete is blocked when related contacts still exist.
    const { service, companyRepo, queryBuilder } = buildService();
    companyRepo.findOne.mockResolvedValue({ id: 'company-1' });
    queryBuilder.getCount.mockResolvedValue(2);

    await expect(service.removeCompany('company-1')).rejects.toMatchObject({
      status: HttpStatus.CONFLICT,
      response: {
        code: BUSINESS_ERROR_CODES.REFERENTIAL_INTEGRITY_VIOLATION,
        details: {
          resource: 'Company',
          id: 'company-1',
          blockingChildren: {
            contacts: 2,
          },
        },
      },
    });
    expect(companyRepo.softDelete).not.toHaveBeenCalled();
  });

  it('soft deletes when the company has no contacts', async () => {
    // Verifies delete succeeds when no related contacts remain.
    const { service, companyRepo, queryBuilder } = buildService();
    companyRepo.findOne.mockResolvedValue({ id: 'company-2' });
    queryBuilder.getCount.mockResolvedValue(0);

    await service.removeCompany('company-2');

    expect(companyRepo.softDelete).toHaveBeenCalledWith('company-2');
  });
});

const API_BASE_PATH = '/api';

// Thrown by request() for both network failures (status undefined) and non-2xx
// HTTP responses (status set). isTransportError() below is the single source of
// truth for "infra-level failure the global interceptor should toast" vs.
// "business error the calling page should handle and display itself".
export class RequestError extends Error {
  constructor(message, status) {
    super(message);
    this.name = 'RequestError';
    this.status = status;
  }
}

// Network failures (fetch itself rejected, no HTTP response at all) and 5xx
// server errors aren't meaningful to a specific page/action, so the global
// interceptor (see App.jsx) shows a generic toast for these. Every other
// status (400/401/403/404/409/422/...) is treated as a business error and
// left to the calling component to interpret and display.
export function isTransportError(error) {
  return !error?.status || error.status >= 500;
}

function buildUrl(path, query) {
  const url = new URL(`${API_BASE_PATH}${path}`, window.location.origin);

  if (query) {
    Object.entries(query).forEach(([key, value]) => {
      if (value !== undefined && value !== null && value !== '') {
        url.searchParams.set(key, value);
      }
    });
  }

  return `${url.pathname}${url.search}`;
}

// vite.config.js proxies /api/* to CRM_BASELINE_API_ORIGIN (backend mounts everything
// under app.setGlobalPrefix('api')), so callers pass paths like '/companies' and this
// prepends the /api prefix + serializes the `query` object as a querystring.
export async function request(path, { query, headers, ...options } = {}) {
  let response;

  try {
    response = await fetch(buildUrl(path, query), {
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...headers,
      },
    });
  } catch {
    throw new RequestError('Network error, please check your connection and try again.', undefined);
  }

  const text = await response.text();
  const data = text ? JSON.parse(text) : null;

  if (!response.ok) {
    const message = data?.message || response.statusText || 'Request failed';
    throw new RequestError(Array.isArray(message) ? message.join(', ') : message, response.status);
  }

  return data;
}

