/bin/bash -lc "cat > backend/src/modules/contact/contact.service.ts <<'EOF'
import { HttpStatus, Injectable } from '@nestjs/common';
import { DataSource } from 'typeorm';
import { AppException } from '../../common/errors/app-exception';
import { BUSINESS_ERROR_CODES } from '../../common/errors/error-codes';
import { CompanyService } from '../company/company.module';
import { ContactCompanyLinkEntity } from './contact-company-link.entity';
import {
  AttachContactCompanyDto,
  ContactCompanyLinkInputDto,
  ContactListQueryDto,
  CreateContactDto,
  DetachContactCompanyDto,
  UpdateContactDto,
} from './dto';
import { ContactEntity } from './contact.entity';
import { ContactRepository } from './contact.repository';

type CompanyLinkRow = {
  contactId: string;
  companyId: string;
  isPrimary: boolean;
  companyName: string;
};

type ContactCompanySummary = {
  id: string;
  name: string;
};

export type ContactResponse = ContactEntity & {
  primaryCompanyId: string | null;
  companies: ContactCompanySummary[];
};

@Injectable()
export class ContactService {
  constructor(
    private readonly contactRepository: ContactRepository,
    private readonly companyService: CompanyService,
    private readonly dataSource: DataSource,
  ) {}

  async createContact(dto: CreateContactDto): Promise<ContactResponse> {
    this.assertExactlyOnePrimaryLink(dto.companyLinks);
    await this.ensureCompaniesExist(dto.companyLinks.map((link) => link.companyId));

    const createdContactId = await this.dataSource.transaction(async (manager) => {
      const contact = manager.create(ContactEntity, {
        name: dto.name,
        email: dto.email,
        phone: dto.phone,
        role: dto.role ?? null,
        lastContactedAt: dto.lastContactedAt ?? null,
      });

      const savedContact = await manager.save(ContactEntity, contact);
      await manager.save(
        ContactCompanyLinkEntity,
        dto.companyLinks.map((link) =>
          manager.create(ContactCompanyLinkEntity, {
            contactId: savedContact.id,
            companyId: link.companyId,
            isPrimary: link.isPrimary,
          }),
        ),
      );

      return savedContact.id;
    });

    return this.getContactById(createdContactId);
  }

  async getContactsList(query: ContactListQueryDto) {
    const [items, total] = await this.contactRepository.findWithFilter(query);

    const limit = query.pageSize ?? 20;
    const page = query.page ?? 1;
    const hydratedItems = await this.hydrateContacts(items);

    return {
      items: hydratedItems,
      total,
      page,
      pageSize: limit,
      totalPages: Math.ceil(total / limit),
    };
  }

  async getContactById(id: string): Promise<ContactResponse> {
    const contact = await this.getContactEntityById(id);
    const hydratedContacts = await this.hydrateContacts([contact]);

    return hydratedContacts[0];
  }

  async updateContact(id: string, dto: UpdateContactDto): Promise<ContactResponse> {
    if (dto.companyLinks) {
      this.assertExactlyOnePrimaryLink(dto.companyLinks);
      await this.ensureCompaniesExist(dto.companyLinks.map((link) => link.companyId));
    }

    await this.dataSource.transaction(async (manager) => {
      const contact = await this.getContactEntityById(id, manager);
      const { companyLinks, ...updatableFields } = dto;
      const mergedContact = manager.merge(ContactEntity, contact, {
        ...updatableFields,
        role:
