    const { service } = buildService();

    await expect(
      service.createContact({
        companyLinks: [],
        name: 'Contact One',
        email: 'contact@test.local',
        phone: '+1-555-0100',
      }),
    ).rejects.toMatchObject({
      status: HttpStatus.BAD_REQUEST,
      response: {
        code: BUSINESS_ERROR_CODES.VALIDATION_ERROR,
        details: {
          errors: [
            {
              field: 'companyLinks',
            },
          ],
        },
      },
    });
  });

  it('rejects detaching a primary link without replacement', async () => {
    const { service, manager } = buildService();

    manager.findOne.mockResolvedValue({ id: 'contact-1', name: 'Contact One' });

    const linkRepository = {
      find: jest.fn().mockResolvedValue([
        { contactId: 'contact-1', companyId: 'company-1', isPrimary: true },
        { contactId: 'contact-1', companyId: 'company-2', isPrimary: false },
      ]),
      findOne: jest.fn(),
      delete: jest.fn(),
      createQueryBuilder: jest.fn(),
      update: jest.fn(),
    };

    manager.getRepository.mockReturnValue(linkRepository);

    await expect(
      service.detachCompanyLink('contact-1', 'company-1', {}),
    ).rejects.toMatchObject({
      status: HttpStatus.CONFLICT,
      response: {
        code: BUSINESS_ERROR_CODES.INVALID_LINK_STATE,
      },
    });

    expect(linkRepository.delete).not.toHaveBeenCalled();
  });

  it('maps missing company in link operations to NOT_FOUND', async () => {
    const { service, companyService } = buildService();
    companyService.getCompanyById.mockRejectedValue(
      new AppException({
        statusCode: HttpStatus.NOT_FOUND,
        code: BUSINESS_ERROR_CODES.ENTITY_NOT_FOUND,
        message: 'Company not found',
      }),
    );

    await expect(
      service.attachCompanyLink('contact-1', {
        companyId: 'company-missing',
      }),
    ).rejects.toMatchObject({
      status: HttpStatus.NOT_FOUND,
      response: {
        code: BUSINESS_ERROR_CODES.NOT_FOUND,
      },
    });
  });
});
