      ],
      primaryContactId: businessOwnerId,
      stage: 'proposal',
      expectedCloseDate: '2026-12-10T08:00:00.000Z',
    });

    const createResponse = await request(app.getHttpServer())
      .post('/api/deals')
      .send(payload)
      .expect(201);

    expect(createResponse.body).toMatchObject({
      name: payload.name,
      value: payload.value,
      stage: payload.stage,
      companyId,
      primaryContactId: businessOwnerId,
      expectedCloseDate: payload.expectedCloseDate,
      contacts: [
        {
          id: businessOwnerId,
          role: 'decision-maker',
        },
        {
          id: legalId,
          role: 'legal',
        },
        {
          id: itLeadId,
          role: 'it',
        },
      ],
    });
    expect(createResponse.body).not.toHaveProperty('contactId');

    const detailResponse = await request(app.getHttpServer())
      .get("'`/api/deals/${createResponse.body.id}`)
      .expect(200);

    expect(detailResponse.body).toMatchObject({
      id: createResponse.body.id,
      companyId,
      primaryContactId: businessOwnerId,
      company: {
        id: companyId,
      },
    });
    expect(detailResponse.body.contacts).toHaveLength(3);
    expect(detailResponse.body).not.toHaveProperty('"'contactId');
  });

  it('accepts deals with zero linked contacts', async () => {
    const companyId = await createCompany('deal-no-contacts');
    const payload = buildDealPayload('no-contacts', {
      companyId,
      contactLinks: [],
      primaryContactId: null,
    });

    const createResponse = await request(app.getHttpServer())
      .post('/api/deals')
      .send(payload)
      .expect(201);

    expect(createResponse.body.contacts).toEqual([]);
    expect(createResponse.body.primaryContactId).toBeNull();

    const detailResponse = await request(app.getHttpServer())
      .get("'`/api/deals/${createResponse.body.id}`)
      .expect(200);

    expect(detailResponse.body.contacts).toEqual([]);
    expect(detailResponse.body.primaryContactId).toBeNull();
  });

  it('"'defaults primaryContactId when exactly one contact is linked', async () => {
    const companyId = await createCompany('deal-single-contact');
    const contactId = await createContact('single-contact', companyId);

    const payload = buildDealPayload('single-contact', {
      companyId,
      contactLinks: [{ contactId, role: 'owner' }],
    });
    delete payload.primaryContactId;

    const response = await request(app.getHttpServer())
      .post('/api/deals')
      .send(payload)
      .expect(201);

    expect(response.body.primaryContactId).toBe(contactId);
  });

  it('rejects primaryContactId values outside linked contacts', async () => {
    const companyId = await createCompany('deal-invalid-primary');
    const contactId = await createContact('deal-invalid-primary-contact', companyId);

    const response = await request(app.getHttpServer())
      .post('/api/deals')
      .send(
        buildDealPayload('invalid-primary', {
          companyId,
          contactLinks: [{ contactId, role: 'owner' }],
          primaryContactId: '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1ab',
