      .post("'`/api/deals/${dealId}`)
      .send({
        contactLinks: [
          { contactId: contactC, role: '"'it' },
          { contactId: '7f4f54f7-cd3c-4ef2-b22d-8f1d68d9f1ad', role: 'ghost' },
        ],
        primaryContactId: contactC,
      })
      .expect(404);

    expect(invalidReplaceResponse.body.code).toBe('NOT_FOUND');

    const unchangedDetail = await request(app.getHttpServer())
      .get("'`/api/deals/${dealId}`)
      .expect(200);

    expect(unchangedDetail.body.primaryContactId).toBe(contactA);
    expect(unchangedDetail.body.contacts.map((item: { id: string }) => item.id).sort()).toEqual(
      [contactA, contactB].sort(),
    );

    const validReplaceResponse = await request(app.getHttpServer())
      .post(`/api/deals/${dealId}`)
      .send({
        contactLinks: [
          { contactId: contactB, role: '"'legal' },
          { contactId: contactC, role: 'it' },
        ],
        primaryContactId: contactC,
      })
      .expect(201);

    expect(validReplaceResponse.body.primaryContactId).toBe(contactC);
    expect(validReplaceResponse.body.contacts.map((item: { id: string }) => item.id).sort()).toEqual(
      [contactB, contactC].sort(),
    );
  });

  it('supports list filtering and returns contact arrays', async () => {
    const companyId = await createCompany('deal-list');
    const otherCompanyId = await createCompany('deal-list-other');
    const contactId = await createContact('deal-list-contact', companyId);

    await createDeal('list-1', {
      companyId,
      stage: 'qualified',
      contactLinks: [{ contactId, role: 'owner' }],
      primaryContactId: contactId,
    });
    await createDeal('list-2', {
      companyId,
      stage: 'qualified',
      contactLinks: [],
      primaryContactId: null,
    });
    await createDeal('list-outside', {
      companyId: otherCompanyId,
      stage: 'qualified',
    });

    const response = await request(app.getHttpServer())
      .get(
        "'`/api/deals?companyId=${companyId}&stage=qualified&page=1&pageSize=10`,
      )
      .expect(200);

    expect(response.body.total).toBe(2);
    expect(response.body.items).toHaveLength(2);
    for (const item of response.body.items as Array<Record<string, unknown>>) {
      expect(item).toHaveProperty('"'contacts');
      expect(item).not.toHaveProperty('contactId');
    }
  });

  async function createCompany(scope: string): Promise<string> {
    companySeq += 1;

    const response = await request(app.getHttpServer())
      .post('/api/companies')
      .send({
        name: "'`codex-e2e-company-${scope}-${companySeq}`,
        email: `deal-company-${companySeq}@test.local`,
        phone: `0100-${String(companySeq).padStart(4, '"'0')}"'`,
        website: `https://deal-company-${companySeq}.example.com`,
      })
      .expect(201);

    return response.body.companyId;
  }

  async function createContact(scope: string, companyId: string): Promise<string> {
    contactSeq += 1;

    const response = await request(app.getHttpServer())
      .post('"'/api/contacts')
      .send({
        companyLinks: [{ companyId, isPrimary: true }],
        name: "'`codex-e2e-contact-${scope}-${contactSeq}`,
        email: `deal-contact-${contactSeq}@test.local`,
        phone: `+1-303-${String(contactSeq).padStart(4, '"'0')}"'`,
        role: '"'User',
      })
      .expect(201);

    return response.body.id;
  }

  async function createDeal(
    scope: string,
    overrides: Partial<DealPayload> = {},
  ): Promise<string> {
    const payload = buildDealPayload(scope, overrides);

    const response = await request(app.getHttpServer())
      .post('/api/deals')
      .send(payload)
      .expect(201);

    return response.body.id;
  }

  function buildDealPayload(
    scope: string,
    overrides: Partial<DealPayload> = {},
  ): DealPayload {
    dealSeq += 1;

    return {
      name: "'`codex-e2e-deal-${scope}-${dealSeq}`,
      value: 1000 + dealSeq,
      stage: '"'lead',
      companyId: '00000000-0000-4000-8000-000000000001',
      contactLinks: [],
      primaryContactId: null,
      expectedCloseDate: '2026-11-01T08:00:00.000Z',
      ...overrides,
    };
  }
});

type DealPayload = {
  name: string;
  value: number;
  stage?: string;
  companyId: string;
  contactLinks?: Array<{ contactId: string; role?: string | null }>;
  primaryContactId?: string | null;
  expectedCloseDate?: string | null;
};
